"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82325"],{83720(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.geo.cep.formato_invalido","status":400,"titulo":"CEP fora do formato"},"descricao":{"codigo":"uniplus.geo.cep.formato_invalido","requisitos":["UNI-REQ-0535"],"oQueAconteceu":["O CEP informado na consulta n\xe3o est\xe1 no formato aceito, e a consulta foi recusada com **400** antes de qualquer busca. O CEP tem exatamente 8 d\xedgitos, escritos juntos (`01001000`) ou com um h\xedfen ou um espa\xe7o entre o quinto e o sexto d\xedgito (`01001-000`). Espa\xe7os no in\xedcio e no fim do CEP s\xe3o ignorados. Quantidade diferente de d\xedgitos, letras, d\xedgitos de outro alfabeto, separador em outra posi\xe7\xe3o, texto vazio ou s\xf3 espa\xe7os n\xe3o s\xe3o aceitos.","A mensagem do erro \xe9 fixa e n\xe3o repete o CEP enviado. Um CEP no formato correto, mas sem endere\xe7o cadastrado, recebe outro erro: [`uniplus.geo.cep.nao_encontrado`](/erros/uniplus.geo.cep.nao_encontrado)."],"comoResolver":["Corrija o CEP para 8 d\xedgitos, com ou sem h\xedfen, e repita a consulta. Se o CEP vem de um campo digitado por quem usa o sistema, retire letras e s\xedmbolos antes de consultar."],"ondeAparece":["Consulta de endere\xe7o pelo CEP (`GET /api/cep/{cep}`), quando o CEP n\xe3o tem 8 d\xedgitos no formato aceito"]},"modulo":{"id":"geo","nome":"Geo","assunto":"Cep"},"origem":{"repositorio":"unifesspa-edu-br/unifesspa-geo-api","commit":"1f1ede7e6ac74707d3a2a86fb9cc079d2f45cff2"}}')}}]);